  {isSport&&step===4&&<div className="wizard-body exercise-builder"><p className="builder-note">اختر ما ستؤديه فعلًا. يمكنك ضبط كل تمرين بعد إضافته.</p>{["دفع","سحب","أرجل","جذع"].map(category=><section key={category}><h3>{category}</h3><div className="exercise-choices">{calisthenicsCatalog.filter(item=>item.category===category).map(item=><button key={item.id} className={exercises.some(x=>x.id===item.id)?"selected":""} onClick={()=>toggleExercise(item)}><span>{item.name}</span><b>{exercises.some(x=>x.id===item.id)?"✓":"+"}</b></button>)}</div></section>)}{exercises.length>0&&<div className="selected-exercises">{exercises.map(item=><article key={item.id}><div><h4>{item.name}</h4><span>{item.measurement==="duration"?"تمرين زمني":"تمرين بالعدات"}</span></div><label>الجولات<input type="number" min="1" max="10" value={item.sets} onChange={event=>updateExercise(item.id,"sets",Number(event.target.value))}/></label>{item.measurement==="duration"?<label>الثواني<input type="number" min="5" value={item.durationSeconds} onChange={event=>updateExercise(item.id,"durationSeconds",Number(event.target.value))}/></label>:<label>العدات<input type="number" min="1" value={item.reps} onChange={event=>updateExercise(item.id,"reps",Number(event.target.value))}/></label>}<label>الراحة<input type="number" min="0" step="15" value={item.restSeconds} onChange={event=>updateExercise(item.id,"restSeconds",Number(event.target.value))}/><small>ث</small></label></article>)}</div>}</div>}
