 const goals=plan.filter(item=>item.nature==="goal"),commitments=plan.filter(item=>item.nature!=="goal");
 const arabicToNumber=(value:string)=>Number(value.replace(/[٠-٩]/g,digit=>"٠١٢٣٤٥٦٧٨٩".indexOf(digit).toString()).match(/\d+/)?.[0]??1);
 const targetSessions=(activity:PlannedActivity)=>activity.schedule.mode==="daily"?days:activity.schedule.mode==="flexible"?arabicToNumber(activity.schedule.value)*(range==="week"?1:4):Math.max(1,weekDays.filter(day=>activity.schedule.value.includes(day)).length)*(range==="week"?1:4);
 const rows=commitments.map(activity=>{const activityRecords=visible.filter(record=>record.activityId===activity.id||(!record.activityId&&record.activity===activity.name));const planned=targetSessions(activity),actual=activityRecords.filter(record=>record.status!=="missed").length,minutes=activityRecords.reduce((sum,record)=>sum+record.minutes,0),average=actual?minutes/actual:0;return{activity,planned,actual,minutes,average,difference:actual-planned}});
